CREATE TABLE Movie_Project (
    Budget FLOAT,
    Filming_Time DATETIME,
    Project_ID INTEGER PRIMARY KEY,
    Project_Name VARCHAR(255),
    Project_Type VARCHAR(255)
);

CREATE TABLE Director (
    Director_ID INTEGER PRIMARY KEY,
    Director_Name VARCHAR(255),
    Email VARCHAR(255),
    Phone_Number VARCHAR(255)
);

CREATE TABLE Actor (
    Actor_ID INTEGER PRIMARY KEY,
    Actor_Name VARCHAR(255),
    Email VARCHAR(255),
    Phone_Number VARCHAR(255)
);

CREATE TABLE Producer (
    Email VARCHAR(255),
    Phone_Number VARCHAR(255),
    Producer_ID INTEGER PRIMARY KEY,
    Producer_Name VARCHAR(255)
);

CREATE TABLE Director_Participate_Project (
    Director_ID INTEGER NOT NULL,
    Project_ID INTEGER NOT NULL,
    PRIMARY KEY (Director_ID, Project_ID),
    FOREIGN KEY (Director_ID) REFERENCES Director(Director_ID),
    FOREIGN KEY (Project_ID) REFERENCES Movie_Project(Project_ID)
);

CREATE TABLE Actor_Participate_Project (
    Actor_ID INTEGER NOT NULL,
    Project_ID INTEGER NOT NULL,
    PRIMARY KEY (Actor_ID, Project_ID),
    FOREIGN KEY (Actor_ID) REFERENCES Actor(Actor_ID),
    FOREIGN KEY (Project_ID) REFERENCES Movie_Project(Project_ID)
);

CREATE TABLE Producer_Participate_Project (
    Producer_ID INTEGER NOT NULL,
    Project_ID INTEGER NOT NULL,
    PRIMARY KEY (Producer_ID, Project_ID),
    FOREIGN KEY (Producer_ID) REFERENCES Producer(Producer_ID),
    FOREIGN KEY (Project_ID) REFERENCES Movie_Project(Project_ID)
);
